## Implementation Blueprint

### Data models and structure (local structural types — defined in ledger.ts, NOT imported)
```ts
// A tool-call content block (assistant only) — the substance is name + arguments.
interface ToolCallContent {
  type: "toolCall";
  id: string;
  name: string;
  arguments: Record<string, unknown>;
}
// Any content block (we only ever inspect toolCall blocks; others are ignored).
type ContentBlock = ToolCallContent | { type: string; [key: string]: unknown };

// Minimal structural message shape. Any Pi AgentMessage variant satisfies this (each carries content:
// string | ContentBlock[]). EXPORTED so tests + tools/rewind.ts can type inputs (like tokens.ts's MessageLike).
export interface MessageLike {
  role?: string;
  content?: string | ContentBlock[];
  [key: string]: unknown;
}

// The deterministic file ledger appended to the rewind note (spec/04 §2.2 — field names are load-bearing).
export interface FileLedger {
  readFiles: string[];       // read/grep/rg/glob/find/ls path/file_path args (de-duped, sorted)
  modifiedFiles: string[];   // write/edit path/file_path + high-confidence bash write paths (de-duped, sorted)
  bashSideEffects: string[]; // non-read-only bash command strings, verbatim (de-duped, sorted)
}
```

